head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07150";
scwin.form = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "* 우회상장법인 정보(" + String(dma_commonInfo.get("apComNm")) + ")"; } },
        { childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            const resultLen = $c.util.getComponent('dlt_resultList').getRowCount();
            for (let i = 0; i < resultLen; i++) {
                if (i < (resultLen - 1)) {
                    if (scwin.form.pershrInvstSaleTotDsp[i] != null) {

                    }
                }
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldstf07150' }); }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07150.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldstf07150: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07150.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07150.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadCapital(r["bzProcsNo"], r["clmInstSeq"], r["comNm"], r["invstChgTpCd"], r["invstDd"], r["invstSaleShrs"], r["pershrInvstSaleAmt"], r["stkNm"], r["incdecRsn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistEtcForm || { elements: [] });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07150.onload" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_resultList_fmt_invstDd
 * @description grd result List fmt invst Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name loadCapital
 * @description load Capital 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} clmInstSeq clmInstSeq
 * @param {String} comNm comNm
 * @param {String} invstChgTpCd invstChgTpCd
 * @param {String} invstDd invstDd
 * @param {*} invstSaleShrs invstSaleShrs
 * @param {*} pershrInvstSaleAmt pershrInvstSaleAmt
 * @param {String} stkNm stkNm
 * @param {*} incdecRsn incdecRsn
 * @returns {void}
 * @hidden N
 */
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    (($c.util.getComponent('slc_invstChgTpCd'))?.setValue?.(invstChgTpCd));
    $c.util.getComponent('ipt_invstDd').setValue($c.date.dateUnFormat(invstDd));
    $c.util.getComponent('ipt_invstSaleShrs').setValue($c.num.formatNumber(invstSaleShrs));
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue($c.num.formatNumber(pershrInvstSaleAmt));
    (($c.util.getComponent('slc_stkNm'))?.setValue?.(stkNm));
    (($c.util.getComponent('slc_incdecRsn'))?.setValue?.(incdecRsn));
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};
